package com.aistock.scheduler.adminrefresh;
import com.aistock.common.BusinessException;import com.aistock.scheduler.task.TaskRepository;import com.aistock.scheduler.admin.*;import java.util.UUID;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static com.aistock.scheduler.adminrefresh.RefreshTestDb.*;
@Tag("mysql") class AdminMarketRefreshRetryMysqlTest {
 AdminTaskActionRepository actions(RefreshTestDb f){return new AdminTaskActionRepository(f.jdbc,new AdminTaskActionPolicy(),true,60,true,true);}
 String failed(RefreshTestDb f){String id=f.repo().submit(ACTOR,"SH600030",command(),context(),NOW).receipt().taskId();f.jdbc.update("update scheduled_task set state='FAILED',error_code='SOURCE_TIMEOUT' where task_id=?",id);return id;}
 AdminTaskActionRecords.Command retry(RefreshTestDb f,String id){return new AdminTaskActionRecords.Command(UUID.randomUUID(),f.jdbc.queryForObject("select revision from scheduled_task where task_id=?",Long.class,id).toString(),"RETRY_TRANSIENT_FAILURE");}
 @Test void newerQueuedTaskBlocksOldPublicAndInternalRetry(){var f=new RefreshTestDb();String old=failed(f);String newer=f.repo().submit(ACTOR,"SH600030",command(),context(),NOW.plusSeconds(61)).receipt().taskId();var actions=actions(f);assertFalse(actions.options(UUID.fromString(old),NOW.plusSeconds(122)).retry().allowed());var result=actions.execute(ACTOR,UUID.fromString(old),AdminTaskActionRecords.Action.RETRY,retry(f,old),NOW.plusSeconds(122));assertEquals("REJECTED",result.receipt().outcome());assertThrows(BusinessException.class,()->new TaskRepository(f.jdbc).retry(old,NOW.plusSeconds(122)));assertEquals(newer,f.jdbc.queryForObject("select active_task_id from admin_market_refresh_guard",String.class));}
 @Test void successfulPublicRetryAtomicallyReclaimsGuardAndCooldown(){var f=new RefreshTestDb();String old=failed(f);var actions=actions(f);assertFalse(actions.options(UUID.fromString(old),NOW.plusSeconds(59)).retry().allowed());var cmd=retry(f,old);var first=actions.execute(ACTOR,UUID.fromString(old),AdminTaskActionRecords.Action.RETRY,cmd,NOW.plusSeconds(60));assertEquals("APPLIED",first.receipt().outcome());assertEquals("QUEUED",new TaskRepository(f.jdbc).get(old).state());assertEquals(java.time.LocalDateTime.of(2026,10,27,12,1),f.jdbc.queryForObject("select last_admitted_at from admin_market_refresh_guard",java.time.LocalDateTime.class));assertEquals(first,actions.execute(ACTOR,UUID.fromString(old),AdminTaskActionRecords.Action.RETRY,cmd,NOW.plusSeconds(61)));}
 @Test void incompleteContextCannotRetryThroughPublicCommand(){var f=new RefreshTestDb();String id=failed(f);f.jdbc.update("delete from admin_market_refresh_context");assertFalse(actions(f).options(UUID.fromString(id),NOW.plusSeconds(61)).retry().allowed());assertEquals("REJECTED",actions(f).execute(ACTOR,UUID.fromString(id),AdminTaskActionRecords.Action.RETRY,retry(f,id),NOW.plusSeconds(61)).receipt().outcome());}

 @Test void terminalNewerTaskAllowsOldRetryAfterCooldown(){var f=new RefreshTestDb();String old=failed(f);String newer=f.repo().submit(ACTOR,"SH600030",command(),context(),NOW.plusSeconds(61)).receipt().taskId();f.jdbc.update("update scheduled_task set state='CANCELLED' where task_id=?",newer);assertEquals("APPLIED",actions(f).execute(ACTOR,UUID.fromString(old),AdminTaskActionRecords.Action.RETRY,retry(f,old),NOW.plusSeconds(122)).receipt().outcome());assertEquals(old,f.jdbc.queryForObject("select active_task_id from admin_market_refresh_guard",String.class));}
 @Test void receiptFailureRollsBackTaskAndGuard(){var f=new RefreshTestDb();String old=failed(f);f.jdbc.execute("create trigger test_refresh_retry_receipt before update on admin_task_operation for each row signal sqlstate '45000' set message_text='test fault'");try{assertThrows(BusinessException.class,()->actions(f).execute(ACTOR,UUID.fromString(old),AdminTaskActionRecords.Action.RETRY,retry(f,old),NOW.plusSeconds(61)));assertEquals("FAILED",new TaskRepository(f.jdbc).get(old).state());assertEquals(java.time.LocalDateTime.of(2026,10,27,12,0),f.jdbc.queryForObject("select last_admitted_at from admin_market_refresh_guard",java.time.LocalDateTime.class));assertEquals(0,f.jdbc.queryForObject("select count(*) from admin_task_operation",Integer.class));}finally{f.jdbc.execute("drop trigger test_refresh_retry_receipt");}}
 @Test void concurrentRetryAndCreateHaveOneActiveAdmission()throws Exception{var f=new RefreshTestDb();String old=failed(f);var cmd=retry(f,old);var gate=new java.util.concurrent.CountDownLatch(1);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{gate.await();return actions(f).execute(ACTOR,UUID.fromString(old),AdminTaskActionRecords.Action.RETRY,cmd,NOW.plusSeconds(61));});var b=pool.submit(()->{gate.await();return f.repo().submit(ACTOR,"SH600030",command(),context(),NOW.plusSeconds(61));});gate.countDown();var ar=a.get(10,java.util.concurrent.TimeUnit.SECONDS);var br=b.get(10,java.util.concurrent.TimeUnit.SECONDS);assertEquals(1,("APPLIED".equals(ar.receipt().outcome())?1:0)+("QUEUED".equals(br.receipt().outcome())?1:0));assertEquals(1,f.jdbc.queryForObject("select count(*) from scheduled_task where state='QUEUED'",Integer.class));assertEquals("QUEUED",f.jdbc.queryForObject("select state from scheduled_task where task_id=(select active_task_id from admin_market_refresh_guard)",String.class));}finally{pool.shutdownNow();}}
 @Test void stockCooldownUsesSeparateConfiguration(){var f=new RefreshTestDb();String id=failed(f);var actions=new AdminTaskActionRepository(f.jdbc,new AdminTaskActionPolicy(),true,60,true,true,300);assertFalse(actions.options(UUID.fromString(id),NOW.plusSeconds(61)).retry().allowed());assertEquals("REJECTED",actions.execute(ACTOR,UUID.fromString(id),AdminTaskActionRecords.Action.RETRY,retry(f,id),NOW.plusSeconds(61)).receipt().outcome());assertEquals("APPLIED",actions.execute(ACTOR,UUID.fromString(id),AdminTaskActionRecords.Action.RETRY,retry(f,id),NOW.plusSeconds(300)).receipt().outcome());}
}